mapper.select:
SELECT order_no, customer_id, device_id, gate_id, order_amount, pay_amount, coupon_amount, order_status, create_time, update_time, remarks
FROM order_info
WHERE customer_id = #{customerId}
ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE customer
SET status = #{status}, update_time = now()
WHERE customer_id = #{customerId}
